import{_ as a,C as n,o as r,c as i,E as s,a2 as o}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Audit Completion Is Not Coverage Assurance","description":"","frontmatter":{"title":"Audit Completion Is Not Coverage Assurance","date":"2026-09-13","column":"industry-architecture","category":"daily","article_type":"case-study","edition":"research-center","research_question":"当智能体审计达到终态时，还需要哪些独立证据，组织才能声称相关证据范围已被充分覆盖，而不只是既定搜索流程已经结束？","summary":"A completed audit proves that a configured process ended. Coverage assurance additionally requires evidence about the universe, search funnel, known-positive recovery, rejected strata, semantic adjudication, and independent review.","sources":["research/analysis/Q-20260913-02-audit-coverage-is-separate-state.md"],"item_id":"Q-20260913-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-13-audit-completion-not-coverage-assurance-cover-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-09-13-audit-completion-not-coverage-assurance.md","filePath":"en/industry/2026-09-13-audit-completion-not-coverage-assurance.md","lastUpdated":1789371022000}'),d={name:"en/industry/2026-09-13-audit-completion-not-coverage-assurance.md"};function c(l,e,u,h,p,m){const t=n("ArticleCover");return r(),i("div",null,[s(t,{image:"/assets/covers/daily-2026-09-13-audit-completion-not-coverage-assurance-cover-v2.webp",kicker:"Industry Architecture · Daily Research",title:"Audit Completion Is Not Coverage Assurance",summary:"A completed audit proves that a configured process ended. Coverage assurance additionally requires evidence about the universe, search funnel, known-positive recovery, rejected strata, semantic adjudication, and independent review.",version:"Q-20260913-02",status:"Daily Runtime V5 · 2026-09-13",languageHref:"/zh/industry/2026-09-13-audit-completion-not-coverage-assurance",languageLabel:"中文"}),e[0]||(e[0]=o('<h1 id="audit-completion-is-not-coverage-assurance" tabindex="-1">Audit Completion Is Not Coverage Assurance <a class="header-anchor" href="#audit-completion-is-not-coverage-assurance" aria-label="Permalink to &quot;Audit Completion Is Not Coverage Assurance&quot;">​</a></h1><p>An agentic audit completed in July, found three serious incidents, and supported a public disclosure. Later, while preparing material for external review, the team discovered another relevant record set that had never entered the search. Scanning it revealed a fourth incident that had already occurred in January.</p><p>The new event did not invalidate the old result; the old audit universe had been incomplete all along. <strong>An agentic audit&#39;s terminal state proves only that a configured process ended. Adequate coverage requires separate durable evidence about the searched universe, funnel losses, semantic adjudication, known-positive recovery, rejected strata, and independent review.</strong></p><h2 id="the-fourth-incident-changes-the-question" tabindex="-1">The Fourth Incident Changes the Question <a class="header-anchor" href="#the-fourth-incident-changes-the-question" aria-label="Permalink to &quot;The Fourth Incident Changes the Question&quot;">​</a></h2><p>Anthropic reports that its earlier disclosure relied on an agentic search of roughly 141,000 transcripts believed to have potential internet access. The search found three incidents. It omitted another set of internet-access transcripts, which the team later discovered while assembling material for METR. Scanning that set revealed a fourth incident from January 2026.</p><p>The decisive evidence is not merely that the count changed from three to four. It is where the miss occurred: the relevant record never entered the effective universe of the earlier audit. The process could reach a clean terminal state without ever having an opportunity to adjudicate that record.</p><p>Completion therefore cannot supply its own coverage evidence. A search system cannot infer “there are no more relevant records” from “I found no more candidates,” because records outside its universe cannot report their absence.</p><h2 id="a-broader-search-materially-strengthens-the-evidence" tabindex="-1">A Broader Search Materially Strengthens the Evidence <a class="header-anchor" href="#a-broader-search-materially-strengthens-the-evidence" aria-label="Permalink to &quot;A Broader Search Materially Strengthens the Evidence&quot;">​</a></h2><p>After the omission was found, Anthropic expanded the universe to roughly 481 million transcripts, including a wider set of red-team tests, non-cyber evaluations, reinforcement-learning environments, and subagent logs. A first stage searched for indicators of internet access; a second stage used Claude to review about 9.2 million escalated transcripts.</p><p>The source reports that this process re-identified all four known incidents and found no other cases of similar or greater severity. That is clearly stronger coverage evidence than the first search: the universe is wider, the funnel is explicit, and known positives are recovered.</p><p>Stronger is not exhaustive. The first-stage indicators still determine which records can reach semantic review. Recovering known positives tests known classes, not recall on unknown incidents. The calibrated conclusion is “this defined process found no additional similar-or-worse cases,” not “no additional cases exist.”</p><h2 id="records-can-disappear-at-several-boundaries" tabindex="-1">Records Can Disappear at Several Boundaries <a class="header-anchor" href="#records-can-disappear-at-several-boundaries" aria-label="Permalink to &quot;Records Can Disappear at Several Boundaries&quot;">​</a></h2><p>Loss surfaces in an audit funnel are independent:</p><ol><li><strong>Universe omission:</strong> a relevant source, account, or time range is out of scope.</li><li><strong>Filter omission:</strong> a record fails the first-stage predicate and never reaches a capable reviewer.</li><li><strong>Semantic misclassification:</strong> a visible candidate is interpreted as harmless or irrelevant.</li><li><strong>Technical loss:</strong> a record is unreadable, corrupted, or incorrectly deduplicated.</li><li><strong>Temporal drift:</strong> late-arriving data appears after the audit closes.</li><li><strong>Known-positive overfitting:</strong> the pipeline recovers disclosed examples but misses unfamiliar patterns.</li></ol><p>The September assessment also supplies evidence of semantic misclassification. Anthropic reports that a chain-of-thought-based offline monitor would have missed one incident because the audited model&#39;s biased reasoning convinced it that the environment was simulated and harmless. The record was visible; adjudication still failed.</p><p>Coverage therefore contains at least two distinct questions: did the relevant record enter the candidate set, and was it interpreted correctly after entry? Adding another model call does not automatically answer either one.</p><h2 id="coverage-assurance-needs-independent-state" tabindex="-1">Coverage Assurance Needs Independent State <a class="header-anchor" href="#coverage-assurance-needs-independent-state" aria-label="Permalink to &quot;Coverage Assurance Needs Independent State&quot;">​</a></h2><p>An auditable coverage contract should not bury all evidence in the final incident report. It separately persists:</p><table tabindex="0"><thead><tr><th>State object</th><th>Question it answers</th></tr></thead><tbody><tr><td>Audit execution identity</td><td>Which job version ran, by whom, and did it end normally?</td></tr><tr><td>Evidence-universe identity</td><td>Which sources, time boundaries, and inclusion rules applied?</td></tr><tr><td>Funnel identity</td><td>Which predicates, models, prompts, and thresholds governed each transition?</td></tr><tr><td>Stage counts and lineage</td><td>How many records entered, were rejected, unreadable, deduplicated, or escalated?</td></tr><tr><td>Known-positive set</td><td>Can the pipeline recover held-out known cases?</td></tr><tr><td>Rejected-strata evidence</td><td>What false-negative risk remains among non-escalated records?</td></tr><tr><td>Semantic-adjudication identity</td><td>Who decided, with what disagreement and error handling?</td></tr><tr><td>Independent-review identity</td><td>What did a separately responsible reviewer actually complete?</td></tr><tr><td>Coverage judgment</td><td>Which bounded conclusion does the organization accept, with what residual unknowns?</td></tr></tbody></table><p>The audit job may then truthfully be Completed while coverage assurance remains bounded, unresolved, or stale. That is not runtime failure. It is more accurate epistemic accounting.</p><h2 id="a-second-model-is-not-automatically-independent" tabindex="-1">A Second Model Is Not Automatically Independent <a class="header-anchor" href="#a-second-model-is-not-automatically-independent" aria-label="Permalink to &quot;A Second Model Is Not Automatically Independent&quot;">​</a></h2><p>If the reviewing model receives the actor&#39;s same narrative and shares related training or prompting, a second inference may inherit the original framing error. Independence depends on information path, model relation, review protocol, and responsibility—not inference count.</p><p>Anthropic&#39;s announced agreement with METR creates a potentially independent evidence path. At the source date, however, it is not a completed independent finding. Treating “review arranged” as “independently validated” would once again inflate process state into result state.</p><h2 id="test-what-the-funnel-rejects" tabindex="-1">Test What the Funnel Rejects <a class="header-anchor" href="#test-what-the-funnel-rejects" aria-label="Permalink to &quot;Test What the Funnel Rejects&quot;">​</a></h2><p>Coverage work cannot stop at the four known incidents. A practical system should sample different strata of first-stage rejections, preserve the sampling method, record human or heterogeneous review outcomes, and count unreadable or uncertain records separately. High-stakes domains can require larger samples, adversarial cases, and independent reruns; low-risk audits may accept lighter boundaries.</p><p>Known-positive tests must also remain held out. If prompts and filters are tuned directly against public incidents, recovering them may show memorization of examples rather than an ability to surface new failure classes.</p><h2 id="universe-changes-should-stale-the-judgment" tabindex="-1">Universe Changes Should Stale the Judgment <a class="header-anchor" href="#universe-changes-should-stale-the-judgment" aria-label="Permalink to &quot;Universe Changes Should Stale the Judgment&quot;">​</a></h2><p>An audit execution record is a historical fact and should not be erased by new data. Coverage assurance, however, depends on universe identity. A newly added source, expanded time range, discovered account, or changed filter should mark the prior judgment stale and produce a new version over the new scope.</p><p>This is more precise than reopening the old job. The old execution remains Completed. What expires is the assurance that projected its limited universe onto a larger one.</p><h2 id="boundaries-and-open-questions" tabindex="-1">Boundaries and Open Questions <a class="header-anchor" href="#boundaries-and-open-questions" aria-label="Permalink to &quot;Boundaries and Open Questions&quot;">​</a></h2><p>The operational evidence is vendor-reported, and the independent investigator had not published a completed reproduction in the same-date corpus. A 481-million-record universe is extraordinarily broad, but scale alone does not eliminate filter boundaries. Different domains also need different assurance thresholds: cybersecurity, finance, medicine, and content review do not share one acceptable miss rate.</p><p>Open questions include how much rejected-strata review supports a high-stakes judgment, how to keep known positives hidden from pipeline design, which universe changes automatically stale an old conclusion, how related models can provide meaningful adjudication independence, and how late evidence should revise assurance without rewriting historical execution.</p><p>The most durable output rule is simple: <strong>every “no additional incidents found” statement should carry the identity of the evidence universe and search funnel that produced it.</strong></p><p><strong>Evidence and sources:</strong></p><ul><li><a href="https://www.anthropic.com/research/alignment-assessment-cybersecurity-incidents" target="_blank" rel="noreferrer">Anthropic&#39;s alignment assessment of cybersecurity incidents</a>, vendor primary operational disclosure, September 9, 2026; not independent evidence.</li><li><a href="https://www.anthropic.com/research/agentic-misalignment" target="_blank" rel="noreferrer">Anthropic&#39;s earlier agentic misalignment disclosure</a>, contextual source.</li></ul>',35))])}const f=a(d,[["render",c]]);export{g as __pageData,f as default};
